package com.example.productapi.controller;
import com.example.productapi.dto.AuthDtos.*; import com.example.productapi.service.AuthService; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/auth") public class AuthController {private final AuthService s; public AuthController(AuthService s){this.s=s;} @PostMapping("/register") ResponseEntity<Void> register(@Valid @RequestBody RegisterRequest r){s.register(r);return ResponseEntity.status(HttpStatus.CREATED).build();} @PostMapping("/login") TokenResponse login(@Valid @RequestBody LoginRequest r){return s.login(r);} @PostMapping("/refresh") TokenResponse refresh(@Valid @RequestBody RefreshRequest r){return s.rotate(r);}}
